style.css:
@-moz-document domain("google.com") {
/* Fondo general */
  body, html {
    background-color: #ffe6f0 !important; /* rosa pastel */
    color: #cc3366 !important; /* rosa fuerte */
  }

  /* Letras de Google en la portada */
  .lnXdpd {
    filter: hue-rotate(330deg) saturate(200%);
  }

  /* Cuadro de búsqueda */
  input[type="text"], input[type="search"] {
    background-color: #ffccd5 !important; /* rosa más suave */
    color: #cc3366 !important; /* texto en rosa más fuerte */
    border: 1px solid #cc3366 !important;
  }

  /* Botones (Buscar con Google, Voy a tener suerte, etc.) */
  input[type="submit"], button {
    background-color: #ffb6c1 !important; /* rosa medio */
    color: #cc3366 !important;
    border: none !important;
  }

  /* Resultados de búsqueda */
  #search, .g, .rc {
    background-color: #ffe6f0 !important; /* rosa pastel */
    color: #cc3366 !important;
  }

  a, a:visited {
    color: #e60073 !important; /* enlaces en rosa fuerte */
  }

  /* Títulos de resultados */
  h3 {
    color: #cc3366 !important;
  }

  /* Pie de página y otros elementos */
  footer, .sfbg, .fbar, .b2hzT {
    background-color: #ffe6f0 !important;
    color: #cc3366 !important;
  }

  /* Correcciones para los hover */
  input[type="submit"]:hover, button:hover {
    background-color: #fdaecb !important;
    color: #800040 !important;
  }
}
